marker = 'function openSettings(){'
assert marker in s
help_js = r'''const GITHUB_REPO_URL='https://github.com/rbleattler/GamesheetsPersonalView';
const GITHUB_FAQ_URL=GITHUB_REPO_URL+'/blob/main/FAQ.md';
const GITHUB_ISSUE_FORM_URL=GITHUB_REPO_URL+'/issues/new?template=myhockeyhub-feedback.yml';
function currentSeasonLabel(){return state.season?.title||catalog().find(x=>String(x.id)===String(state.seasonId))?.title||`Season ${state.seasonId}`}
function openHelp(){openDrawer('Help & feedback','Quick answers, the full FAQ, and an easy way to send feedback',`<div class="help-grid"><section class="help-card"><h3>Quick help</h3><p>The most common things people look for:</p><div class="quick-help"><div><span>🔎</span><span><b>Change leagues:</b> open Settings → Find league / season.</span></div><div><span>👥</span><span><b>Add teams:</b> My Teams → Manage, then choose division first.</span></div><div><span>★</span><span><b>Follow players:</b> Players → Add Players, select one or more, then Add Players.</span></div><div><span>📍</span><span><b>Save a rink:</b> tap the star beside a venue on a game card.</span></div></div><div class="help-actions"><a class="soft" href="${GITHUB_FAQ_URL}" target="_blank" rel="noopener">Read the full FAQ ↗</a></div></section><section class="help-card"><h3>Something wrong or missing?</h3><p>No technical expertise is required. You can describe what you saw in plain language and MyHockeyHub will package the useful app context for you.</p><div class="help-actions"><button id="helpBuildReport" class="primary">Report a problem or suggestion</button><a class="soft issue-template-link" href="${GITHUB_ISSUE_FORM_URL}" target="_blank" rel="noopener">Open guided GitHub form ↗</a></div></section><section class="help-card"><h3>Screenshots</h3><p>The app cannot upload files to GitHub on its own without asking you to sign in and authorize access. After GitHub opens, you can paste or drag screenshots into the issue before submitting it.</p></section></div>`);$('#helpBuildReport').onclick=openFeedbackForm}
function feedbackContext(){return{version:'3.6',view:state.view,seasonId:String(state.seasonId||''),season:currentSeasonLabel(),url:location.href,userAgent:navigator.userAgent,viewport:`${window.innerWidth}×${window.innerHeight}`}}
function feedbackMarkdown(){const kind=$('#feedbackKind')?.value||'Problem / bug',summary=($('#feedbackSummary')?.value||'').trim(),details=($('#feedbackDetails')?.value||'').trim(),expected=($('#feedbackExpected')?.value||'').trim(),steps=($('#feedbackSteps')?.value||'').trim(),includeContext=$('#feedbackIncludeContext')?.checked!==false,c=feedbackContext();let body=`## Type\n${kind}\n\n## Summary\n${summary||'(No summary entered)'}\n\n## What happened / what would you like to see?\n${details||'(No details entered)'}\n`;if(expected)body+=`\n## What did you expect?\n${expected}\n`;if(steps)body+=`\n## Steps to reproduce\n${steps}\n`;if(includeContext)body+=`\n## App context\n- MyHockeyHub: V${c.version}\n- View: ${c.view}\n- League / season: ${c.season}\n- Season ID: ${c.seasonId}\n- Page: ${c.url}\n- Browser: ${c.userAgent}\n- Viewport: ${c.viewport}\n`;body+='\n## Screenshots\nIf helpful, paste or drag screenshots into this issue on GitHub before submitting.\n\n---\nGenerated from the MyHockeyHub Help & Feedback screen.';return{kind,summary,body}}
function feedbackIssueUrl(){const r=feedbackMarkdown(),prefix=r.kind.startsWith('Suggestion')?'[Suggestion]':r.kind.startsWith('Data')?'[Data]':r.kind.startsWith('Question')?'[Question]':'[Bug]',title=`${prefix} ${r.summary||'MyHockeyHub feedback'}`,u=new URL(GITHUB_REPO_URL+'/issues/new');u.searchParams.set('title',title);u.searchParams.set('body',r.body);return u.toString()}
async function copyFeedbackMarkdown(){const status=$('#feedbackStatus');try{await navigator.clipboard.writeText(feedbackMarkdown().body);if(status)status.textContent='Report copied to your clipboard.'}catch{if(status)status.textContent='Could not access the clipboard. You can still continue to GitHub.'}}
function openFeedbackForm(){const c=feedbackContext();openDrawer('Send feedback','Plain-language feedback is perfect — technical details are optional',`<div class="feedback-grid"><div><label class="label">What kind of feedback?</label><select id="feedbackKind"><option>Problem / bug</option><option>Suggestion / feature request</option><option>Data issue</option><option>Question</option></select></div><div><label class="label">Short summary</label><input id="feedbackSummary" type="text" maxlength="180" placeholder="Example: My team schedule is missing a game"></div><div><label class="label">What happened / what would you like to see?</label><textarea id="feedbackDetails" maxlength="4000" placeholder="Tell us what you noticed in your own words."></textarea></div><div><label class="label">What did you expect? <span class="muted">(optional)</span></label><textarea id="feedbackExpected" maxlength="2500" placeholder="What would have been more useful?"></textarea></div><div><label class="label">Steps to reproduce <span class="muted">(optional)</span></label><textarea id="feedbackSteps" maxlength="2500" placeholder="Example: Open Schedule → choose 12U A → tap…"></textarea></div><label style="display:flex;gap:9px;align-items:flex-start"><input id="feedbackIncludeContext" type="checkbox" checked style="margin-top:3px"><span><b>Include basic app context</b><span class="feedback-note" style="display:block">Version, current view, league/season, page URL, browser description, and screen size. No saved teams, players, or other local preferences are included.</span></span></label><div class="feedback-context">Current context: V${esc(c.version)} · ${esc(c.view)} · ${esc(c.season)} · ID ${esc(c.seasonId)}</div><div class="feedback-note">When you continue, GitHub opens a pre-filled issue for review. A GitHub account is required to submit it. Add screenshots there by pasting or dragging them into the issue.</div><div class="help-actions"><button id="feedbackOpenGithub" class="primary">Continue to GitHub</button><button id="feedbackCopy" class="soft">Copy report</button><a class="soft issue-template-link" href="${GITHUB_ISSUE_FORM_URL}" target="_blank" rel="noopener">Use guided form instead ↗</a></div><div id="feedbackStatus" class="feedback-status"></div></div>`);$('#feedbackOpenGithub').onclick=()=>{const summary=($('#feedbackSummary')?.value||'').trim(),details=($('#feedbackDetails')?.value||'').trim(),status=$('#feedbackStatus');if(!summary||!details){if(status)status.textContent='Please add a short summary and a little detail first.';return}window.open(feedbackIssueUrl(),'_blank','noopener')};$('#feedbackCopy').onclick=copyFeedbackMarkdown}
'''
s = s.replace(marker, help_js + '\n' + marker, 1)

