s = s.replace(bind_old, bind_new, 1)

startup_old = "fillSeason();loadSeason();"
startup_new = "const hasSavedSeason=!!(localStorage.getItem('gsv3.seasonId')||localStorage.getItem('gsv2.seasonId')||localStorage.getItem('dvhl.seasonId'));const pickerRequested=sessionStorage.getItem('myhockeyhub.openSeasonFinder')==='1';if(pickerRequested)sessionStorage.removeItem('myhockeyhub.openSeasonFinder');fillSeason();if(pickerRequested||!hasSavedSeason){els.status.textContent='Choose a league / season to get started';openSeasonFinder()}else loadSeason();"
