items = '''  <div class="items">\n    <div class="item"><div class="check">✓</div><div><b>Friendlier first visit</b><span>New users are invited to choose their league or season before the app loads instead of silently landing in the original default league.</span></div></div>\n    <div class="item"><div class="check">✓</div><div><b>Help is always nearby</b><span>A ? button beside Settings opens quick guidance, the full FAQ, and feedback options.</span></div></div>\n    <div class="item"><div class="check">✓</div><div><b>Easier feedback</b><span>Build a plain-language report in the app and open a pre-filled GitHub issue, or use the guided GitHub issue form.</span></div></div>\n  </div>\n'''
stable = stable[:start_items] + items + stable[end_items:]
old_go = '''  const go = () => {\n    localStorage.setItem(KEY, CURRENT);\n    loading.classList.add('show');\n    card.hidden = true;\n    location.replace(TARGET);\n  };'''
new_go = '''  const go = (openFinder = false) => {\n    localStorage.setItem(KEY, CURRENT);\n    if (openFinder) sessionStorage.setItem('myhockeyhub.openSeasonFinder', '1');\n    loading.classList.add('show');\n    card.hidden = true;\n    location.replace(TARGET);\n  };'''
assert old_go in stable
stable = stable.replace(old_go, new_go, 1)
old_new_user = '''  // Truly new users do not need a changelog gate; send them straight to the app.\n  if (!last && !legacy && !modern) {\n    localStorage.setItem(KEY, CURRENT);\n    location.replace(TARGET);\n    return;\n  }'''
new_new_user = '''  // A first-time visitor should choose the league/season that matters to them.\n  if (!last && !legacy && !modern) {\n    card.hidden = false;\n    document.getElementById('kicker').textContent = 'Welcome';\n    document.getElementById('title').textContent = 'Find your hockey';\n    document.getElementById('intro').textContent = 'Start by choosing the league or season you care about. You can change it anytime later from Settings.';\n    document.querySelector('.items').innerHTML = `\n      <div class="item"><div class="check">1</div><div><b>Choose your league</b><span>Search by league name, season name, familiar acronym, or GameSheet season ID.</span></div></div>\n      <div class="item"><div class="check">2</div><div><b>Add your teams and players</b><span>Personalize the app after the schedule loads.</span></div></div>\n      <div class="item"><div class="check">?</div><div><b>Help is built in</b><span>The ? button in the app opens quick help, the FAQ, and feedback options.</span></div></div>`;\n    const btn = document.getElementById('continueBtn');\n    btn.textContent = 'Choose league / season';\n    btn.onclick = () => go(true);\n    return;\n  }'''
assert old_new_user in stable
stable = stable.replace(old_new_user, new_new_user, 1)
stable = stable.replace("document.getElementById('continueBtn').onclick = go;", "document.getElementById('continueBtn').onclick = () => go(false);", 1)
(ROOT / 'gamesheets_plus.html').write_text(stable, encoding='utf-8')

index = (ROOT / 'index.html').read_text(encoding='utf-8')
index = index.replace('<div class="version"><div class="tag current">V3.5</div>', '<div class="version"><div class="tag">V3.5</div>', 1)
