card = '<div class="version"><div class="tag current">V3.6</div><div class="desc"><b>First-run onboarding, Help, and feedback</b><span>New visitors now choose their league up front. Added a persistent Help button with FAQ access plus a friendly in-app feedback builder that opens a pre-filled GitHub issue.</span></div><a class="open" href="v3.6.html">Open V3.6</a></div>\n'
